typedef unsigned int u_int;

class vector3d
{
public:
  float x, y, z;

  vector3d() {}
  vector3d(float a, float b, float c) : x(a), y(b), z(c) {}
  vector3d operator+(const vector3d& v) const { return vector3d(x + v.x, y + v.y, z + v.z); }
  vector3d operator*(float f) const { return vector3d(x * f, y * f, z * f); }
  vector3d& operator+=(const vector3d& v) { x += v.x; y += v.y; z += v.z; return *this; }
};

enum WaveRegionEnum { WAVE_REGION_DUMMY };
enum WaveMarkerEnum { WAVE_MarkerInvalid = -1 };

extern float WAVE_ToleranceDefaultD, WAVE_ToleranceDefaultZ;
struct WaveTolerance
{
  float dthresh;
  float zthresh;
  WaveTolerance() { dthresh = WAVE_ToleranceDefaultD; zthresh = WAVE_ToleranceDefaultZ; }
};

struct WavePositionHint { char data[1]; };

class CollideCallStruct
{
public:
  CollideCallStruct(const vector3d& pos, vector3d* n, vector3d* c, WaveRegionEnum* r, WavePositionHint* h)
  { position = pos; normal = n; current = c; region = r; hint = h; }

  vector3d position;
  vector3d* normal;
  vector3d* current;
  WaveRegionEnum* region;
  WavePositionHint* hint;
  WaveTolerance tolerance;
};

extern float WAVE_MeshMinX;
extern float WAVE_MeshMaxX;
extern float WAVE_MeshMinZ;
extern float WAVE_MeshMaxZ;

bool WAVE_CheckCollision(CollideCallStruct&, bool, bool, bool, bool = false,
                         WaveMarkerEnum = WAVE_MarkerInvalid,
                         WaveMarkerEnum = WAVE_MarkerInvalid);
void WAVE_GlobalCurrent(vector3d* current);
float WATER_Altitude(float x, float z);
void WATER_Normal(float x, float z, float& nx, float& ny, float& nz);

class surfing_object
{
  char pad0[0x44];
  WavePositionHint wave_hint;
  char pad1[0x260 - 0x45];
  bool use_hint;
  char pad2[0x2c4 - 0x261];
  float current_x_mult;

public:
  bool floating_ai(vector3d& position, vector3d& normal, float dt);
};

bool surfing_object::floating_ai (vector3d& position, vector3d& normal, float dt)
{
  // make the object flow with the water
  if ((position.x < WAVE_MeshMaxX) && (position.x > WAVE_MeshMinX) &&
      (position.z < WAVE_MeshMaxZ) && (position.z > WAVE_MeshMinZ))
  {
    vector3d current;
    CollideCallStruct collide (position, &normal, &current, 0, &wave_hint);
    use_hint = WAVE_CheckCollision (collide, use_hint, false, false);
    current.x *= current_x_mult;

    position = collide.position + current * dt;
  }
  else
  {
    vector3d current;

    position.y = WATER_Altitude (position.x, position.z);
    WAVE_GlobalCurrent (&current);
    WATER_Normal (position.x, position.z, normal.x, normal.y, normal.z);

    position += current * dt;
    use_hint = false;
  }

  return true;
}
